import * as fs from "fs";
const input = fs.readFileSync(0, "utf8").trim();
____

exam.solution:
import * as fs from "fs";
const input = fs.readFileSync(0, "utf8").trim();
const lines = input.split("\n");
const n = Number(lines[0]);
type Cmd =
  | { kind: "push"; value: number }
  | { kind: "add" }
  | { kind: "mul" }
  | { kind: "dup" }
  | { kind: "pop" };
function parse(line: string): Cmd {
  const [op, arg] = line.trim().split(/\s+/);
  if (op === "push") return { kind: "push", value: Number(arg) };
  if (op === "add") return { kind: "add" };
  if (op === "mul") return { kind: "mul" };
  if (op === "dup") return { kind: "dup" };
  return { kind: "pop" };
}
const stack: number[] = [];
for (let i = 1; i <= n; i++) {
  const cmd = parse(lines[i]);
  switch (cmd.kind) {
    case "push":
      stack.push(cmd.value);
      break;
    case "add": {
      const b = stack.pop() ?? 0;
      const a = stack.pop() ?? 0;
      stack.push(a + b);
      break;
    }
    case "mul": {
      const b = stack.pop() ?? 0;
      const a = stack.pop() ?? 0;
      stack.push(a * b);
      break;
    }
    case "dup":
      stack.push(stack[stack.length - 1] ?? 0);
      break;
    case "pop":
      stack.pop();
      break;
    default: {
      const exhaustive: never = cmd;
      throw new Error(exhaustive);
    }
  }
}
