import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = sc.nextInt();
        int min = a[0];
        int max = a[0];
        long sum = 0;
        for (int i = 0; i < n; i++) {
            if (a[i] < min) min = a[i];
            if (a[i] > max) max = a[i];
            sum += a[i];
        }
        double mean = (double) sum / n;
        int above = 0;
        for (int i = 0; i < n; i++) {
            if (a[i] > mean) above++;
        }
        System.out.println(min);
