        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) g[i][j] = sc.nextInt();
        }
        int[][] next = new int[r][c];
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                int live = 0;
                for (int di = -1; di <= 1; di++) {
                    for (int dj = -1; dj <= 1; dj++) {
                        if (di == 0 && dj == 0) continue;
                        int ni = i + di;
                        int nj = j + dj;
                        if (ni < 0 || ni >= r || nj < 0 || nj >= c) continue;
                        live += g[ni][nj];
